/* Service page styles, scoped only to .service-page */
.service-page {
  --service-radius: 16px;
  --service-border: rgba(0, 0, 0, 0.06);
  --service-shadow: 0 10px 30px rgba(0, 0, 0, 0.08);
}

.service-page .service-hero {
  display: flex;
  gap: 18px;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  margin: 10px 0 18px;
}

.service-page .service-hero > p {
  margin: 0;
}

.service-page .service-hero__text {
  flex: 1 1 360px;
  min-width: 280px;
}

.service-page .service-kicker {
  opacity: 0.82;
  font-size: 14px;
  letter-spacing: 0.3px;
  margin-bottom: 6px;
}

.service-page .service-title {
  margin: 0 0 10px;
  line-height: 1.25;
}

.service-page .service-subtitle {
  margin: 0 0 14px;
  opacity: 0.92;
}

.service-page .service-hero__img {
  width: min(220px, 32vw);
  max-width: 100%;
  height: auto;
  border-radius: var(--service-radius);
  box-shadow: var(--service-shadow);
}

.service-page .service-cta {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin: 6px 0 10px;
}

.service-page .service-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 10px 14px;
  border-radius: 999px;
  border: 1px solid var(--service-border);
  background: var(--card-bg, rgba(255, 255, 255, 0.85));
  color: var(--font-color, #222);
  text-decoration: none;
  transition: transform 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
}

.service-page .service-btn:hover {
  transform: translateY(-1px);
  box-shadow: 0 12px 25px rgba(0, 0, 0, 0.10);
}

.service-page .service-btn--primary {
  border: none;
  color: #fff;
  background: linear-gradient(135deg, #3b82f6, #8b5cf6);
}

.service-page .service-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 6px;
}

.service-page .service-badges span {
  display: inline-flex;
  padding: 6px 10px;
  border-radius: 999px;
  background: rgba(59, 130, 246, 0.10);
  border: 1px solid rgba(59, 130, 246, 0.18);
  font-size: 13px;
}

.service-page .service-lead {
  margin: 10px 0 14px;
  padding: 14px 16px;
  border-radius: var(--service-radius);
  border: 1px solid var(--service-border);
  background: var(--card-bg, rgba(255, 255, 255, 0.85));
}

.service-page h2 i {
  margin-right: 8px;
  opacity: 0.9;
}

.service-page .service-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(420px, 1fr));
  gap: 16px;
  margin: 10px auto 0;
}

.service-page .service-card {
  padding: 16px 16px 14px;
  border-radius: var(--service-radius);
  border: 1px solid var(--service-border);
  background: var(--card-bg, rgba(255, 255, 255, 0.85));
  box-shadow: 0 10px 24px rgba(0, 0, 0, 0.06);
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.service-page .service-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 14px 34px rgba(0, 0, 0, 0.10);
}

.service-page .service-card__head {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  margin-bottom: 10px;
}

.service-page .service-card__icon {
  width: 44px;
  height: 44px;
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  background: linear-gradient(135deg, rgba(59, 130, 246, 0.95), rgba(139, 92, 246, 0.95));
  flex: 0 0 auto;
}

.service-page .service-card__title {
  font-weight: 700;
  font-size: 16px;
  line-height: 1.2;
  margin: 2px 0 4px;
}

.service-page .service-card__desc {
  opacity: 0.80;
  font-size: 13px;
}

.service-page .service-card ul {
  margin: 0;
  padding-left: 18px;
}

.service-page .service-card li {
  margin: 6px 0;
}

.service-page .service-steps {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 12px;
  margin-top: 10px;
}

.service-page .service-step {
  padding: 12px 14px;
  border-radius: var(--service-radius);
  border: 1px solid var(--service-border);
  background: var(--card-bg, rgba(255, 255, 255, 0.85));
}

.service-page .service-step b {
  display: inline-flex;
  width: 22px;
  height: 22px;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: rgba(59, 130, 246, 0.12);
  margin-right: 6px;
}

.service-page .service-footer {
  margin-top: 18px;
}

.service-page .service-footer__card {
  padding: 16px;
  border-radius: calc(var(--service-radius) + 2px);
  border: 1px solid rgba(139, 92, 246, 0.25);
  background: linear-gradient(135deg, rgba(59, 130, 246, 0.10), rgba(139, 92, 246, 0.10));
}

.service-page .service-footer__title {
  font-weight: 800;
  margin-bottom: 6px;
}

.service-page .service-footer__desc {
  opacity: 0.9;
  margin-bottom: 10px;
}





